//! Unit tests of kcov_build.zig's parts that decide what kcov is: the four source
//! patches (and that a new kcov they do not match is refused by their marker count),
//! the generated byte-array sources, and the reader of libelf.a. The build itself is
//! :kcov_dist, held to the sha256 of identity.bzl by :kcov_identity, and to be
//! reproducible by :kcov_reproducible.
const std = @import("std");
const K = @import("kcov_build.zig");
const t = std.testing;

fn arena() std.heap.ArenaAllocator {
    return std.heap.ArenaAllocator.init(t.allocator);
}

test "patch no_cpu_pin: the affinity call becomes a marked no-op, indentation kept" {
    var ar = arena();
    defer ar.deinit();
    const a = ar.allocator();
    const src = "void f() {\n\t  panic_if(sched_setaffinity(pid, CPU_ALLOC_SIZE(max_cpu), set) < 0, \"Can't set CPU affinity. Coincident won't work\");\n  other();\n}\n";
    const out = try K.applyPatch(a, .no_cpu_pin, src);
    try t.expectEqualStrings("void f() {\n\t  (void) pid; /* KOMIRA PATCH: no CPU pin */\n  other();\n}\n", out);
    // A changed call (a new kcov) matches nothing: no marker added.
    const other = "  panic_if(sched_setaffinity(pid, size, set) < 0, \"x\");\n";
    try t.expectEqualStrings(other, try K.applyPatch(a, .no_cpu_pin, other));
    // A line with trailing text is not the statement.
    const trailing = "  panic_if(sched_setaffinity(pid, CPU_ALLOC_SIZE(max_cpu), set) < 0, \"Can't set CPU affinity. Coincident won't work\"); // x\n";
    try t.expectEqualStrings(trailing, try K.applyPatch(a, .no_cpu_pin, trailing));
}

test "patch not_other_exit: only the line after `case ev_exit:`" {
    var ar = arena();
    defer ar.deinit();
    const a = ar.allocator();
    const src = "  case ev_exit:\n    m_exitCode = ev.data;\n    break;\n  case ev_other:\n    m_exitCode = ev.data;\n";
    const out = try K.applyPatch(a, .not_other_exit, src);
    try t.expectEqualStrings("  case ev_exit:\n    /* KOMIRA PATCH: not the status of another process */\n    break;\n  case ev_other:\n    m_exitCode = ev.data;\n", out);
    // The first occurrence on the line only.
    const two = "case ev_exit:\n  m_exitCode = ev.data; m_exitCode = ev.data;\n";
    try t.expectEqualStrings("case ev_exit:\n  /* KOMIRA PATCH: not the status of another process */ m_exitCode = ev.data;\n", try K.applyPatch(a, .not_other_exit, two));
}

test "patch signal_exit: inside the range from `case ev_signal_exit:` to `case ev_exit_first_process:`, ends included" {
    var ar = arena();
    defer ar.deinit();
    const a = ar.allocator();
    const src = "m_exitCode = ev.data;\ncase ev_signal_exit:\n  m_exitCode = ev.data;\ncase ev_exit_first_process:\n  m_exitCode = ev.data;\ncase ev_x:\n  m_exitCode = ev.data;\n";
    const out = try K.applyPatch(a, .signal_exit, src);
    try t.expectEqualStrings("m_exitCode = ev.data;\ncase ev_signal_exit:\n  m_exitCode = 128 + ev.data; /* KOMIRA PATCH: as a shell reports it */\ncase ev_exit_first_process:\n  m_exitCode = ev.data;\ncase ev_x:\n  m_exitCode = ev.data;\n", out);
    // A range with no end runs to the end of the file.
    const open = "case ev_signal_exit:\n  m_exitCode = ev.data;\n  m_exitCode = ev.data;\n";
    try t.expectEqual(@as(usize, 2), std.mem.count(u8, try K.applyPatch(a, .signal_exit, open), "KOMIRA PATCH"));
}

test "patch first_child: the childrenLeft test is replaced, nothing else" {
    var ar = arena();
    defer ar.deinit();
    const a = ar.allocator();
    const src = "\t\tif (!childrenLeft())\n\t\t\tbreak;\n  if (!childrenLeft()) {\n";
    try t.expectEqualStrings("\t\tif (who == m_firstChild) /* KOMIRA PATCH: the test, not another process */\n\t\t\tbreak;\n  if (!childrenLeft()) {\n", try K.applyPatch(a, .first_child, src));
}

test "a text without trailing newline keeps none; a patch is idempotent in count" {
    var ar = arena();
    defer ar.deinit();
    const a = ar.allocator();
    try t.expectEqualStrings("if (who == m_firstChild) /* KOMIRA PATCH: the test, not another process */", try K.applyPatch(a, .first_child, "if (!childrenLeft())"));
    const ls = try K.splitKeep(a, "a\nb\n\nc");
    try t.expectEqual(@as(usize, 4), ls.len);
    try t.expectEqualStrings("c", ls[3]);
}

test "bin2c: sixteen bytes to a line, lower-case hex, the GeneratedData tail" {
    var ar = arena();
    defer ar.deinit();
    const a = ar.allocator();
    var bytes: [18]u8 = undefined;
    for (&bytes, 0..) |*b, i| b.* = @intCast(i * 15);
    const out = try K.bin2c(a, &.{.{ "f", "name" }}, &.{&bytes});
    try t.expectEqualStrings(
        "#include <stdint.h>\n#include <stdlib.h>\n#include <generated-data-base.hh>\nusing namespace kcov;\n" ++
            "const uint8_t name_data_raw[] = {\n" ++
            "0x00,0x0f,0x1e,0x2d,0x3c,0x4b,0x5a,0x69,0x78,0x87,0x96,0xa5,0xb4,0xc3,0xd2,0xe1,\n" ++
            "0xf0,0xff,\n" ++
            "};\nGeneratedData name_data(name_data_raw, sizeof(name_data_raw));\n",
        out,
    );
    // Two files: one include header, two arrays.
    const two = try K.bin2c(a, &.{ .{ "a", "x" }, .{ "b", "y" } }, &.{ "A", "B" });
    try t.expectEqual(@as(usize, 1), std.mem.count(u8, two, "#include <stdint.h>"));
    try t.expect(std.mem.indexOf(u8, two, "x_data_raw[] = {\n0x41,\n};") != null);
    try t.expect(std.mem.indexOf(u8, two, "y_data_raw[] = {\n0x42,\n};") != null);
}

fn arHeader(out: *std.ArrayList(u8), name: []const u8, size: usize) !void {
    var h: [60]u8 = undefined;
    @memset(&h, ' ');
    @memcpy(h[0..name.len], name);
    _ = try std.fmt.bufPrint(h[48..58], "{d}", .{size});
    h[58] = '`';
    h[59] = '\n';
    try out.appendSlice(&h);
}

test "arMembers: GNU names, a long-name table, the symbol table skipped, odd sizes padded" {
    var ar = arena();
    defer ar.deinit();
    const a = ar.allocator();
    var d = std.ArrayList(u8).init(a);
    try d.appendSlice("!<arch>\n");
    try arHeader(&d, "/", 4);
    try d.appendSlice("\x00\x00\x00\x00");
    const long = "a_very_long_object_name.o/\n";
    try arHeader(&d, "//", long.len);
    try d.appendSlice(long);
    try d.append(0); // padding: 27 is odd
    try arHeader(&d, "crc32.o/", 3);
    try d.appendSlice("abc\n");
    try arHeader(&d, "/0", 2);
    try d.appendSlice("zz");
    const ms = try K.arMembers(a, d.items);
    try t.expectEqual(@as(usize, 2), ms.len);
    try t.expectEqualStrings("crc32.o", ms[0].name);
    try t.expectEqualStrings("abc", ms[0].data);
    try t.expectEqualStrings("a_very_long_object_name.o", ms[1].name);
    try t.expectEqualStrings("zz", ms[1].data);
    try t.expectError(error.NotAr, K.arMembers(a, "not an archive"));
    try t.expectError(error.BadAr, K.arMembers(a, "!<arch>\nshort header"));
}
